$insA = $pdo->prepare('INSERT INTO avaliacoes (curso_id, modulo_id, titulo, nota_minima, ativo) VALUES (?, ?, ?, 70, 1)');
$selA = $pdo->prepare('SELECT id FROM avaliacoes WHERE curso_id = ? AND modulo_id = ?');
$cntQ = $pdo->prepare('SELECT COUNT(*) FROM avaliacao_questoes WHERE avaliacao_id = ?');
$insQ = $pdo->prepare('INSERT INTO avaliacao_questoes (avaliacao_id, enunciado, ordem) VALUES (?, ?, ?)');
$insAlt = $pdo->prepare('INSERT INTO avaliacao_alternativas (questao_id, texto, correta, ordem) VALUES (?, ?, ?, ?)');
$pdo->beginTransaction();
try {
    foreach ($dados as $av) {
        $selA->execute([$cursoId, $av['modulo_id']]);
        $avId = (int)$selA->fetchColumn();
        if (!$avId) { $insA->execute([$cursoId, $av['modulo_id'], $av['titulo']]); $avId = (int)$pdo->lastInsertId(); }
        $cntQ->execute([$avId]);
        if ((int)$cntQ->fetchColumn() > 0) { echo "{$av['modulo_id']}: ja tinha questoes, mantida\n"; continue; }
        foreach ($av['questoes'] as $i => $q) {
            $insQ->execute([$avId, $q['enunciado'], $i + 1]);
            $qId = (int)$pdo->lastInsertId();
            foreach ($q['alternativas'] as $j => $alt) { $insAlt->execute([$qId, $alt['texto'], $alt['correta'], $j + 1]); }
        }
        echo "{$av['modulo_id']}: " . count($av['questoes']) . " questoes criadas (avaliacao id={$avId})\n";
    }
    $pdo->commit();
} catch (Throwable $e) { $pdo->rollBack(); exit('ERRO: ' . $e->getMessage() . "\n"); }
echo 'total de avaliacoes do curso: ' . $pdo->query("SELECT COUNT(*) FROM avaliacoes WHERE curso_id = {$cursoId}")->fetchColumn() . "\n";
@unlink(__FILE__);
